#!/usr/bin/env python3
"""
patch_modal_overview_layout.py

Rebuilds the Overview layout to the redesign mockup.

⚠ WHY THE PREVIOUS ATTEMPT DID NOT LOOK LIKE THE MOCKUP.

Increment 4 INSERTED cells into the existing markup. But the mockup is not an
addition to that markup, it is a different layout: the old Overview is a plain
two-column list of label/value pairs with full-width stacked textareas; the
mockup has a bordered grid with hairline dividers and two side-by-side note
cards. Adding cells to a list produces a longer list, which is exactly what
shipped -- ORDER TYPE and PO / REFERENCE as two more rows of the old layout.

So this replaces the two blocks wholesale rather than patching into them.

WHAT IS PRESERVED VERBATIM: the claim control. It is a ~40-line IIFE carrying
stage-aware ownership logic -- claimed by me, by someone else, or unclaimed,
each with a different control -- and it is lifted into the new grid as text
rather than retyped.

No marker strings: "already applied" is derived from the anchor and the
replacement. See patch_modal_overview_4.py for why.

    cd ~/cabinet-orders
    python3 patch_modal_overview_layout.py
    npx tsc --noEmit 2>&1 | grep -E "error TS"; echo "EXIT: $?"   # EXIT:1 = clean
"""

import sys
from pathlib import Path

TARGET = "components/OrderModal.tsx"

OLD_GRID  = '          {/* Details grid */}\n          <div className="px-6 py-5 space-y-4" style={SECTION_BORDER}>\n            <div className="grid grid-cols-2 gap-4">\n              <div>\n                <p className={LABEL}>Source</p>\n                <span\n                  className="text-[10px] uppercase tracking-wider px-2 py-px rounded-full font-medium"\n                  style={\n                    liveOrder.source === "Shopify"\n                      ? { background: "rgba(184,130,106,0.15)", color: "#d9a888", border: "0.5px solid rgba(184,130,106,0.40)" }\n                      : liveOrder.source === "Manual"\n                      ? { background: "rgba(145,165,151,0.18)", color: "#b8d0bd", border: "0.5px solid rgba(145,165,151,0.45)" }\n                      : { background: "rgba(140,170,200,0.18)", color: "#a8c8e0", border: "0.5px solid rgba(140,170,200,0.40)" }\n                  }\n                >\n                  {liveOrder.source === "Manual" ? "Custom" : liveOrder.source}\n                </span>\n              </div>\n              <div>\n                <p className={LABEL}>SKU</p>\n                <p className="text-xs font-mono text-cream/65">{liveOrder.sku || "—"}</p>\n              </div>\n              <div>\n                {(() => {\n                  // Stage-aware ownership:\n                  //   New / New claim: claimed_by is the source of truth.\n                  //     An order rolled back to New is unclaimed until\n                  //     someone picks it up again — entered_by is kept\n                  //     in the DB for audit but hidden here.\n                  //   Later stages: entered_by takes precedence.\n                  const isNewStage = liveOrder.stage === "New" || liveOrder.stage === "New claim";\n                  const ownerName = isNewStage\n                    ? liveOrder.claimed_by ?? null\n                    : liveOrder.entered_by ?? liveOrder.claimed_by ?? null;\n                  // ownerName is now a team_members.id; look up by id, render m.name\n                  const ownerMember = ownerName ? team.find(m => m.id === ownerName) : null;\n                  const claimedBy = liveOrder.claimed_by ?? null;\n                  const isClaimedByMe = !!currentUserId && claimedBy === currentUserId;\n                  const isClaimedByOther = !!claimedBy && !isClaimedByMe;\n                  // Claim/release affordance only on New stages — once\n                  // entered, ownership is tracked by entered_by which the\n                  // PATCH endpoint maintains on stage transitions.\n                  const showClaimUi = isNewStage;\n                  return (\n                    <>\n                      <div className="flex items-center justify-between gap-2">\n                        <p className={LABEL}>Team member</p>\n                        {showClaimUi && (\n                          isClaimedByMe ? (\n                            <button\n                              type="button"\n                              onClick={() => handleClaim(null)}\n                              disabled={claimBusy}\n                              className="text-[10px] uppercase tracking-wider text-cream/55 hover:text-cream transition-colors disabled:opacity-40"\n                            >\n                              {claimBusy ? "..." : "Release"}\n                            </button>\n                          ) : isClaimedByOther ? (\n                            <span className="text-[10px] uppercase tracking-wider text-amber-300/70" title={`Claimed by ${ownerMember?.name ?? claimedBy}`}>\n                              Locked\n                            </span>\n                          ) : (\n                            <button\n                              type="button"\n                              onClick={() => handleClaim(currentUserId ?? null)}\n                              disabled={claimBusy || !currentUserId}\n                              className="text-[10px] uppercase tracking-wider px-2 py-0.5 rounded-full bg-terracotta/20 border border-terracotta/45 text-terracotta hover:bg-terracotta/30 transition-all disabled:opacity-40"\n                            >\n                              {claimBusy ? "..." : "Claim"}\n                            </button>\n                          )\n                        )}\n                      </div>\n                      <div className="mt-1">\n                        {!ownerName ? (\n                          <p className="text-xs text-cream/35 italic">unclaimed</p>\n                        ) : ownerMember ? (\n                          <div className="flex items-center gap-2">\n                            <AvatarWithProfile member={ownerMember} size="sm" />\n                            <span className="text-xs text-cream/65">{ownerMember.name}</span>\n                          </div>\n                        ) : (\n                          // Fallback when the team row isn\\\'t loaded yet\n                          <span className="text-xs text-cream/65">{ownerName}</span>\n                        )}\n                      </div>\n                    </>\n                  );\n                })()}\n              </div>\n              <div>\n                <p className={LABEL}>Date</p>\n                <p className="text-xs text-cream/65">{liveOrder.date}</p>\n              </div>\n              <div>\n                <p className={LABEL}>Order type</p>\n                <p className="text-xs text-cream/65">{GROUP_LABEL[liveOrder.type] ?? liveOrder.type}</p>\n              </div>\n              <div>\n                {/* The reference a MANUFACTURER sees. Internal -- never shown to\n                    a customer, who knows only the order number. */}\n                <p className={LABEL}>PO / Reference</p>\n                <p className="text-xs font-mono text-cream/65">{poReference(liveOrder)}</p>\n              </div>\n              <div>\n                {/* Scheduled, not actual. A delivery date the customer has not\n                    been given is not a promise, and this is the internal view. */}\n                <p className={LABEL}>Delivery target</p>\n                <p className="text-xs text-cream/65">\n                  {liveOrder.scheduled_delivery_date || liveOrder.delivery_date || "Not set"}\n                </p>\n              </div>\n            </div>\n\n'
NEW_GRID  = '          {/* ORDER INFO -- a bordered grid with hairline dividers, per the\n              redesign mockup. This was a plain two-column list of label/value\n              pairs; adding cells to it was how ORDER TYPE and PO / REFERENCE\n              ended up as two more rows of the old layout rather than the grid. */}\n          <div className="px-6 py-5 space-y-4" style={SECTION_BORDER}>\n            <div className="flex items-center justify-between mb-2">\n              <p className={LABEL}>Order info</p>\n            </div>\n            <div\n              className="grid grid-cols-2 md:grid-cols-4 rounded-brand overflow-hidden"\n              style={{ border: "0.5px solid rgba(255,255,255,0.12)" }}\n            >\n              <div className="px-4 py-3" style={{ borderTop: "0.5px solid rgba(255,255,255,0.08)", borderLeft: "0.5px solid rgba(255,255,255,0.08)" }}>\n                <p className={LABEL}>Source</p>\n                <span\n                  className="text-[10px] uppercase tracking-wider px-2 py-px rounded-full font-medium inline-block mt-1"\n                  style={\n                    liveOrder.source === "Shopify"\n                      ? { background: "rgba(184,130,106,0.15)", color: "#d9a888", border: "0.5px solid rgba(184,130,106,0.40)" }\n                      : liveOrder.source === "Manual"\n                      ? { background: "rgba(145,165,151,0.18)", color: "#b8d0bd", border: "0.5px solid rgba(145,165,151,0.45)" }\n                      : { background: "rgba(140,170,200,0.18)", color: "#a8c8e0", border: "0.5px solid rgba(140,170,200,0.40)" }\n                  }\n                >\n                  {liveOrder.source === "Manual" ? "Custom" : liveOrder.source}\n                </span>\n              </div>\n              <div className="px-4 py-3" style={{ borderTop: "0.5px solid rgba(255,255,255,0.08)", borderLeft: "0.5px solid rgba(255,255,255,0.08)" }}>\n                <p className={LABEL}>Order date</p>\n                <p className="text-xs text-cream/65 mt-1">{liveOrder.date}</p>\n              </div>\n              {/* The claim control, lifted verbatim -- it carries stage-aware\n                  ownership logic (mine / someone else\'s / unclaimed) that is not\n                  worth retyping into a new layout. */}\n              <div className="px-4 py-3" style={{ borderTop: "0.5px solid rgba(255,255,255,0.08)", borderLeft: "0.5px solid rgba(255,255,255,0.08)" }}>\n                {(() => {\n                  // Stage-aware ownership:\n                  //   New / New claim: claimed_by is the source of truth.\n                  //     An order rolled back to New is unclaimed until\n                  //     someone picks it up again — entered_by is kept\n                  //     in the DB for audit but hidden here.\n                  //   Later stages: entered_by takes precedence.\n                  const isNewStage = liveOrder.stage === "New" || liveOrder.stage === "New claim";\n                  const ownerName = isNewStage\n                    ? liveOrder.claimed_by ?? null\n                    : liveOrder.entered_by ?? liveOrder.claimed_by ?? null;\n                  // ownerName is now a team_members.id; look up by id, render m.name\n                  const ownerMember = ownerName ? team.find(m => m.id === ownerName) : null;\n                  const claimedBy = liveOrder.claimed_by ?? null;\n                  const isClaimedByMe = !!currentUserId && claimedBy === currentUserId;\n                  const isClaimedByOther = !!claimedBy && !isClaimedByMe;\n                  // Claim/release affordance only on New stages — once\n                  // entered, ownership is tracked by entered_by which the\n                  // PATCH endpoint maintains on stage transitions.\n                  const showClaimUi = isNewStage;\n                  return (\n                    <>\n                      <div className="flex items-center justify-between gap-2">\n                        <p className={LABEL}>Team member</p>\n                        {showClaimUi && (\n                          isClaimedByMe ? (\n                            <button\n                              type="button"\n                              onClick={() => handleClaim(null)}\n                              disabled={claimBusy}\n                              className="text-[10px] uppercase tracking-wider text-cream/55 hover:text-cream transition-colors disabled:opacity-40"\n                            >\n                              {claimBusy ? "..." : "Release"}\n                            </button>\n                          ) : isClaimedByOther ? (\n                            <span className="text-[10px] uppercase tracking-wider text-amber-300/70" title={`Claimed by ${ownerMember?.name ?? claimedBy}`}>\n                              Locked\n                            </span>\n                          ) : (\n                            <button\n                              type="button"\n                              onClick={() => handleClaim(currentUserId ?? null)}\n                              disabled={claimBusy || !currentUserId}\n                              className="text-[10px] uppercase tracking-wider px-2 py-0.5 rounded-full bg-terracotta/20 border border-terracotta/45 text-terracotta hover:bg-terracotta/30 transition-all disabled:opacity-40"\n                            >\n                              {claimBusy ? "..." : "Claim"}\n                            </button>\n                          )\n                        )}\n                      </div>\n                      <div className="mt-1">\n                        {!ownerName ? (\n                          <p className="text-xs text-cream/35 italic">unclaimed</p>\n                        ) : ownerMember ? (\n                          <div className="flex items-center gap-2">\n                            <AvatarWithProfile member={ownerMember} size="sm" />\n                            <span className="text-xs text-cream/65">{ownerMember.name}</span>\n                          </div>\n                        ) : (\n                          // Fallback when the team row isn\\\'t loaded yet\n                          <span className="text-xs text-cream/65">{ownerName}</span>\n                        )}\n                      </div>\n                    </>\n                  );\n                })()}\n              </div>\n              <div className="px-4 py-3" style={{ borderTop: "0.5px solid rgba(255,255,255,0.08)", borderLeft: "0.5px solid rgba(255,255,255,0.08)" }}>\n                <p className={LABEL}>Order type</p>\n                <p className="text-xs text-cream/65 mt-1">{GROUP_LABEL[liveOrder.type] ?? liveOrder.type}</p>\n              </div>\n              <div className="px-4 py-3" style={{ borderTop: "0.5px solid rgba(255,255,255,0.08)", borderLeft: "0.5px solid rgba(255,255,255,0.08)" }}>\n                <p className={LABEL}>SKU</p>\n                <p className="text-xs font-mono text-cream/65 mt-1 truncate">{liveOrder.sku || "\\u2014"}</p>\n              </div>\n              <div className="px-4 py-3" style={{ borderTop: "0.5px solid rgba(255,255,255,0.08)", borderLeft: "0.5px solid rgba(255,255,255,0.08)" }}>\n                {/* The reference a MANUFACTURER sees. Internal -- never shown to\n                    a customer, who knows only the order number. */}\n                <p className={LABEL}>PO / Reference</p>\n                <p className="text-xs font-mono text-cream/65 mt-1">{poReference(liveOrder)}</p>\n              </div>\n              <div className="px-4 py-3" style={{ borderTop: "0.5px solid rgba(255,255,255,0.08)", borderLeft: "0.5px solid rgba(255,255,255,0.08)" }}>\n                {/* Scheduled, not actual. A date the customer has not been given\n                    is not a promise, and this is the internal view. */}\n                <p className={LABEL}>Delivery target</p>\n                <p className="text-xs text-cream/65 mt-1">\n                  {liveOrder.scheduled_delivery_date || liveOrder.delivery_date || "Not set"}\n                </p>\n              </div>\n              <div className="px-4 py-3" style={{ borderTop: "0.5px solid rgba(255,255,255,0.08)", borderLeft: "0.5px solid rgba(255,255,255,0.08)" }}>\n                <p className={LABEL}>Stage age</p>\n                <p className="text-xs text-cream/65 mt-1">{formatStageAge(hoursInStage(liveOrder))}</p>\n              </div>\n            </div>\n\n'
OLD_NOTES = '          {/* Customer-facing notes — Quote orders get structured display, others get plain textarea */}\n            {liveOrder.source === "Manual" && liveOrder.notes?.includes("QUOTE REQUEST") ? (\n              <QuoteInfoPanel notes={liveOrder.notes} />\n            ) : (\n              <div>\n                <p className={LABEL}>Customer Notes</p>\n                <textarea\n                  value={notes}\n                  onChange={(e) => { setNotes(e.target.value); setNotesChanged(true); }}\n                  placeholder="Add notes visible to the customer / written into the Shopify order…"\n                  rows={6}\n                  className="w-full rounded-brand p-3 text-[12px] resize-none transition-colors placeholder:text-cream/25"\n                  style={{\n                    background: "rgba(255,255,255,0.04)",\n                    border: "0.5px solid rgba(255,255,255,0.15)",\n                    color: "rgba(240,236,228,0.85)",\n                    fontSize: "16px",\n                  }}\n                />\n                {notesChanged && (\n                  <button\n                    onClick={handleSaveNotes}\n                    className="mt-2 text-[11px] uppercase tracking-wider font-medium transition-colors text-terracotta hover:brightness-110"\n                  >\n                    Save notes →\n                  </button>\n                )}\n              </div>\n            )}\n\n            {/* Internal notes — staff-only, never sent to Shopify, shown in red on export PDF */}\n            <div className="mt-3">\n              <div className="flex items-center gap-2 mb-2">\n                <p className="text-[10px] uppercase tracking-[0.16em] font-medium" style={{ color: "rgba(232,144,144,0.75)" }}>\n                  Internal Notes\n                </p>\n                <span\n                  className="text-[8px] uppercase tracking-wider px-1.5 py-px rounded-full font-medium"\n                  style={{\n                    background: "rgba(232,144,144,0.12)",\n                    color: "rgba(232,144,144,0.85)",\n                    border: "0.5px solid rgba(232,144,144,0.30)",\n                  }}\n                >\n                  staff only\n                </span>\n              </div>\n              <textarea\n                value={internalNotes}\n                onChange={(e) => { setInternalNotes(e.target.value); setInternalNotesChanged(true); }}\n                placeholder="Visible to staff and on the export PDF. Never sent to Shopify or the customer."\n                rows={4}\n                className="w-full rounded-brand p-3 text-[12px] resize-none transition-colors placeholder:text-cream/25"\n                style={{\n                  background: "rgba(232,144,144,0.04)",\n                  border: "0.5px dashed rgba(232,144,144,0.30)",\n                  color: "rgba(240,236,228,0.90)",\n                  fontSize: "16px",\n                }}\n              />\n              {internalNotesChanged && (\n                <button\n                  onClick={handleSaveInternalNotes}\n                  className="mt-2 text-[11px] uppercase tracking-wider font-medium transition-colors text-terracotta hover:brightness-110"\n                >\n                  Save internal notes →\n                </button>\n              )}\n            </div>\n          </div>\n\n'
NEW_NOTES = '          {/* Notes -- two cards side by side, per the mockup. These were two\n              always-open full-width textareas stacked vertically. */}\n          <div className="px-6 py-5 grid grid-cols-1 md:grid-cols-2 gap-3" style={SECTION_BORDER}>\n            <div className="rounded-brand p-3" style={{ border: "0.5px solid rgba(255,255,255,0.12)" }}>\n              <p className={LABEL}>Customer note</p>\n              {liveOrder.source === "Manual" && liveOrder.notes?.includes("QUOTE REQUEST") ? (\n                /* A quote request is structured text, not a note somebody\n                   typed -- it gets its own panel rather than a textarea. */\n                <QuoteInfoPanel notes={liveOrder.notes} />\n              ) : (<>\n              <p className="text-[10px] text-cream/35 mb-2">\n                Visible to the customer &middot; written to the Shopify order\n              </p>\n              <textarea\n                value={notes}\n                onChange={(e) => { setNotes(e.target.value); setNotesChanged(true); }}\n                placeholder="No customer note yet."\n                rows={4}\n                className="w-full rounded-brand p-2.5 text-[12px] resize-none transition-colors placeholder:text-cream/25"\n                style={{\n                  background: "rgba(255,255,255,0.04)",\n                  border: "0.5px solid rgba(255,255,255,0.12)",\n                  color: "rgba(240,236,228,0.90)",\n                  fontSize: "16px",\n                }}\n              />\n              {notesChanged && (\n                <button\n                  onClick={handleSaveNotes}\n                  className="mt-2 text-[11px] uppercase tracking-wider font-medium transition-colors text-terracotta hover:brightness-110"\n                >\n                  Save note\n                </button>\n              )}\n              </>)}\n            </div>\n            <div className="rounded-brand p-3" style={{ border: "0.5px solid rgba(232,144,144,0.28)" }}>\n              <div className="flex items-center gap-2">\n                <p className={LABEL}>Internal note</p>\n                <span\n                  className="text-[9px] uppercase tracking-wider px-1.5 py-px rounded-full"\n                  style={{\n                    background: "rgba(232,144,144,0.12)",\n                    color: "rgba(232,144,144,0.85)",\n                    border: "0.5px solid rgba(232,144,144,0.30)",\n                  }}\n                >\n                  staff only\n                </span>\n              </div>\n              <p className="text-[10px] text-cream/35 mb-2">\n                Visible to staff and on the export PDF. Never sent to Shopify.\n              </p>\n              <textarea\n                value={internalNotes}\n                onChange={(e) => { setInternalNotes(e.target.value); setInternalNotesChanged(true); }}\n                placeholder="No internal note yet."\n                rows={4}\n                className="w-full rounded-brand p-2.5 text-[12px] resize-none transition-colors placeholder:text-cream/25"\n                style={{\n                  background: "rgba(232,144,144,0.04)",\n                  border: "0.5px solid rgba(232,144,144,0.25)",\n                  color: "rgba(240,236,228,0.90)",\n                  fontSize: "16px",\n                }}\n              />\n              {internalNotesChanged && (\n                <button\n                  onClick={handleSaveInternalNotes}\n                  className="mt-2 text-[11px] uppercase tracking-wider font-medium transition-colors text-terracotta hover:brightness-110"\n                >\n                  Save internal note\n                </button>\n              )}\n            </div>\n          </div>\n          </div>\n\n'
STEPS = [
    ("ORDER INFO grid", OLD_GRID, NEW_GRID),
    ("notes as side-by-side cards", OLD_NOTES, NEW_NOTES),
]


def main() -> int:
    path = Path.cwd() / TARGET
    if not path.is_file():
        print(f"ABORT: {TARGET} not found. Run from ~/cabinet-orders.")
        return 1
    text = path.read_text(encoding="utf-8")
    original = text

    def already_applied(anchor, replacement, t):
        if replacement == "":
            return anchor not in t
        return replacement in t

    planned, skipped, problems = [], [], []
    for label, anchor, replacement in STEPS:
        if anchor == replacement:
            problems.append(f"{label} -- replacement is identical to the anchor"); continue
        if replacement and replacement in anchor:
            problems.append(f"{label} -- replacement is a substring of the anchor"); continue
        if already_applied(anchor, replacement, text):
            skipped.append(label); continue
        n = text.count(anchor)
        if n == 1:
            planned.append((label, anchor, replacement))
        else:
            problems.append(f"{label} -- anchor matches {n} time(s), expected 1; file has drifted")

    if problems:
        print("ABORT -- nothing written:")
        for p in problems: print("  " + p)
        return 1
    if not planned:
        print("Already applied in full. Nothing to do.")
        for s in skipped: print("  skip " + s)
        return 0

    for label, anchor, replacement in planned:
        text = text.replace(anchor, replacement, 1)
    for label, anchor, replacement in planned:
        if not already_applied(anchor, replacement, text):
            print(f"ABORT -- nothing written: {label} did not take effect")
            return 1

    # ── PARSE IT ────────────────────────────────────────────────────────────
    #
    # Counting braces cannot see JSX nesting. Three attempts at this layout
    # shipped balanced-but-broken markup -- a <div> opened and never closed,
    # while every brace matched. This writes the result to a temp file and runs
    # a real TSX parser over it before touching the real one.
    #
    # esbuild is already a Next.js dependency, so it is present in node_modules.
    import subprocess, tempfile, os, shutil
    esbuild = shutil.which("esbuild") or "node_modules/.bin/esbuild"
    if os.path.exists(esbuild):
        with tempfile.NamedTemporaryFile("w", suffix=".tsx", delete=False, encoding="utf-8") as tmp:
            tmp.write(text)
            tmp_path = tmp.name
        try:
            r = subprocess.run([esbuild, "--jsx=automatic", "--outfile=/dev/null", tmp_path],
                               capture_output=True, text=True)
            if r.returncode != 0:
                print("ABORT -- nothing written: the result does not parse as TSX.")
                for line in (r.stderr or "").splitlines()[:20]:
                    print("  " + line.replace(tmp_path, TARGET))
                return 1
        finally:
            os.unlink(tmp_path)
    else:
        print("  !!   esbuild not found -- parse check SKIPPED. Read the diff.")

    if text.count("{") != text.count("}") or text.count("(") != text.count(")"):
        print("ABORT -- nothing written: delimiters unbalanced after patch")
        return 1

    # Verify what the patch DID: the claim control and both note savers must
    # survive. Losing handleClaim would leave an order that cannot be claimed
    # from the modal at all.
    for kept in ("handleClaim(null)", "handleClaim(currentUserId ?? null)",
                 "handleSaveNotes", "handleSaveInternalNotes"):
        if kept not in text:
            print(f"ABORT -- nothing written: lost {kept}")
            return 1

    path.write_text(text, encoding="utf-8")
    for s in skipped: print("  skip " + s)
    for label, *_ in planned: print(f"  ok   {label}")
    print(f"\n{TARGET}: {len(original.splitlines())} -> {len(text.splitlines())} lines")
    return 0


if __name__ == "__main__":
    sys.exit(main())
